PANELS = [("pairs", "Training pairs: straight lines that cross"), ("ddpm", "Diffusion, DDIM paths: length ratio 1.023"),
          ("rf1", "Rectified flow: S = 0.060"), ("rf2", "After one reflow: S = 0.00001")]
W, H = 780, 728; PW, PH = 370, 310; GX, GY = 20, 40
X0, X1, Y0, Y1 = -3, 7, -3.6, 3.6
def svg(th, acc, acc2):
    ink, mut, grid, surf = th
    o = [f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {W} {H}" width="{W}" height="{H}" font-family="Arial,Helvetica,sans-serif" role="img">']
    o.append(f'<rect width="{W}" height="{H}" fill="{surf}"/>')
    for k, (key, title) in enumerate(PANELS):
        ox = 10 + (k % 2) * (PW + GX); oy = 30 + (k // 2) * (PH + GY)
        sx = lambda x: ox + (x - X0) / (X1 - X0) * PW
        sy = lambda y: oy + PH - (y - Y0) / (Y1 - Y0) * PH
        o.append(f'<rect x="{ox}" y="{oy}" width="{PW}" height="{PH}" fill="none" stroke="{grid}" stroke-width="1.5"/>')
        o.append(f'<text x="{ox + PW/2}" y="{oy - 9}" fill="{ink}" font-size="15" text-anchor="middle" font-weight="bold">{title}</text>')
        if key == "pairs":
            for a, b, c, d in D["pairs"]:
                o.append(f'<line x1="{sx(a):.1f}" y1="{sy(b):.1f}" x2="{sx(c):.1f}" y2="{sy(d):.1f}" stroke="{acc}" stroke-width="1.1" opacity="0.75"/>')
            starts = [(p[0], p[1]) for p in D["pairs"]]; ends = [(p[2], p[3]) for p in D["pairs"]]
        else:
            for tr in D[key]:
                o.append(f'<polyline fill="none" stroke="{acc}" stroke-width="1.3" opacity="0.8" points="{" ".join(f"{sx(x):.1f},{sy(y):.1f}" for x, y in tr)}"/>')
            starts = [tr[0] for tr in D[key]]; ends = [tr[-1] for tr in D[key]]
        for x, y in starts:
            o.append(f'<circle cx="{sx(x):.1f}" cy="{sy(y):.1f}" r="2.6" fill="{surf}" stroke="{mut}" stroke-width="1.2"/>')
        for x, y in ends:
            o.append(f'<circle cx="{sx(x):.1f}" cy="{sy(y):.1f}" r="2.8" fill="{acc2}"/>')
    ly = H - 12
    o.append(f'<circle cx="200" cy="{ly-4}" r="4" fill="{surf}" stroke="{mut}" stroke-width="1.5"/><text x="210" y="{ly}" fill="{ink}" font-size="13">start: a noise sample</text>')
    o.append(f'<circle cx="400" cy="{ly-4}" r="4" fill="{acc2}"/><text x="410" y="{ly}" fill="{ink}" font-size="13">end: a point on the two moons</text>')
    o.append('</svg>'); return "\n".join(o)
light = ('#0b1a33', '#4a5b78', '#dde5f2', '#ffffff')
dark = ('#e8eefc', '#9fb0cf', '#22355a', '#0b162d')
open(sys.argv[1] + '.svg', 'w').write(svg(light, '#2a78d6', '#eb6834'))
open(sys.argv[1] + '-dark.svg', 'w').write(svg(dark, '#3987e5', '#d95926'))
